{-| @Pudu.Backend.Runtime.Process — signal policy and the inherited standard
    descriptors visible to source operations. -}
module Pudu.Backend.Runtime.Process (processIoLines) where

import Data.Text (Text)

processIoLines :: [Text]
processIoLines =
  [ "#include <errno.h>"
  , "#if !defined(_WIN32)"
  , "#include <poll.h>"
  , "#endif"
  , "#if defined(__APPLE__) || defined(__FreeBSD__) || defined(__OpenBSD__) || defined(__NetBSD__)"
  , "#include <fcntl.h>"
  , "#include <sys/event.h>"
  , "#elif defined(__linux__)"
  , "#include <fcntl.h>"
  , "#include <sys/epoll.h>"
  , "#endif"
  , ""
  , "static inline void pudu_prepare_descriptors(void) {"
  , "  static int prepared = 0;"
  , "  if (prepared) return;"
  , "  prepared = 1;"
  , "#if defined(__APPLE__) || defined(__FreeBSD__) || defined(__OpenBSD__) || defined(__NetBSD__) || defined(__linux__)"
  , "  unsigned int missing = 0;"
  , "  for (int descriptor = 0; descriptor < 3; ++descriptor) {"
  , "    if (fcntl(descriptor, F_GETFD) < 0 && errno == EBADF) missing |= 1u << descriptor;"
  , "  }"
  , "  if (missing == 0) return;"
  , "#if defined(__linux__)"
  , "  int backend = epoll_create1(EPOLL_CLOEXEC);"
  , "#else"
  , "  int backend = kqueue();"
  , "#endif"
  , "  if (backend < 0) return;"
  , "  if (backend < 3) missing &= ~(1u << backend);"
  , "  if (missing != 0) {"
  , "    int control[2];"
  , "    if (pipe(control) != 0) return;"
  , "    (void)fcntl(control[0], F_SETFD, FD_CLOEXEC);"
  , "    (void)fcntl(control[1], F_SETFD, FD_CLOEXEC);"
  , "    int flags = fcntl(control[1], F_GETFL);"
  , "    if (flags >= 0) (void)fcntl(control[1], F_SETFL, flags | O_NONBLOCK);"
  , "  }"
  , "#endif"
  , "}"
  , ""
  , "static inline int pudu_wait_writable(int descriptor) {"
  , "#if !defined(_WIN32)"
  , "  struct pollfd writable = {descriptor, POLLOUT, 0};"
  , "  int ready = poll(&writable, 1, 0);"
  , "  if (ready == 0) {"
  , "    do { ready = poll(&writable, 1, -1); } while (ready < 0 && errno == EINTR);"
  , "    if (ready < 0) return errno;"
  , "  }"
  , "#else"
  , "  (void)descriptor;"
  , "#endif"
  , "  return 0;"
  , "}"
  , ""
  , "#ifdef SIGPIPE"
  , "static void pudu_pipe_handler(int number) {"
  , "  /* Rearm on C implementations with one-shot signal handlers. */"
  , "  (void)signal(number, pudu_pipe_handler);"
  , "}"
  , "#endif"
  , "static inline void pudu_prepare_io(void) {"
  , "#ifdef SIGPIPE"
  , "  (void)signal(SIGPIPE, pudu_pipe_handler);"
  , "#endif"
  , "  pudu_prepare_descriptors();"
  , "}"
  ]
